/* Loading: built-in window.RT_DATA + ad-hoc FileReader (no fetch/XHR). */
import { RtData, RunLog } from "./types";

declare global {
  interface Window { RT_DATA?: RtData; }
}

/** Built-in bundle generated by viewer/tools/embed.py (may be absent). */
export function builtinData(): RtData | null {
  return window.RT_DATA ?? null;
}

/** Load an ad-hoc run log chosen via <input type="file">. */
export function loadLogFile(file: File): Promise<RunLog> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("파일 읽기 실패"));
    reader.onload = () => {
      try {
        resolve(JSON.parse(String(reader.result)) as RunLog);
      } catch (e) {
        reject(new Error("JSON 파싱 실패: " + String(e)));
      }
    };
    reader.readAsText(file);
  });
}
